OPENFILE "scores.txt" FOR READ
// ... READFILE statements here ...
CLOSEFILE "scores.txt"

OPENFILE "log.txt" FOR WRITE
// ... WRITEFILE statements here ...
CLOSEFILE "log.txt"

// Program run 1: create a brand-new log, discarding anything previously in it
OPENFILE "log.txt" FOR WRITE
WRITEFILE "log.txt", "Student,Score"
WRITEFILE "log.txt", "Aisha,72"
CLOSEFILE "log.txt"
// log.txt now contains exactly two lines: "Student,Score" and "Aisha,72"

// Program run 2 (later): add a further record without losing what is already there
OPENFILE "log.txt" FOR APPEND
WRITEFILE "log.txt", "Carlos,58"
CLOSEFILE "log.txt"
// log.txt now contains three lines: the original two, plus "Carlos,58" added at the end.
// Opening log.txt FOR WRITE again at this point would instead erase all three lines.
